import{_ as a,c as e,ag as s,o as t}from"./chunks/framework.kMCHP7uL.js";const p=JSON.parse('{"title":"zig 命令","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"environment/zig-command.md","filePath":"environment/zig-command.md"}'),n={name:"environment/zig-command.md"};function o(d,i,c,h,l,g){return t(),e("div",null,i[0]||(i[0]=[s('<h1 id="zig-命令" tabindex="-1"><code>zig</code> 命令 <a class="header-anchor" href="#zig-命令" aria-label="Permalink to &quot;`zig` 命令&quot;">​</a></h1><p>安裝好 Zig 和編輯器後，我們來了解一下 <code>zig</code> 命令行的基本用法。</p><p>這個命令非常強大，它不僅涵蓋了項目的創建、構建、測試和運行，甚至還能用於部署，或作為 C/C++ 的編譯器及依賴管理工具。這一切都得益於 Zig 強大的自舉編譯器。</p><p>以下列出一些常用命令：</p><h2 id="zig-build" tabindex="-1"><code>zig build</code> <a class="header-anchor" href="#zig-build" aria-label="Permalink to &quot;`zig build`&quot;">​</a></h2><p>構建項目。該命令會自動在當前及父目錄中查找 <code>build.zig</code> 文件並執行構建流程。</p><h2 id="zig-build-obj" tabindex="-1"><code>zig build-obj</code> <a class="header-anchor" href="#zig-build-obj" aria-label="Permalink to &quot;`zig build-obj`&quot;">​</a></h2><p>將指定的 Zig 源文件編譯成對象文件（<code>.o</code> 文件）。</p><h2 id="zig-build-test" tabindex="-1"><code>zig build test</code> <a class="header-anchor" href="#zig-build-test" aria-label="Permalink to &quot;`zig build test`&quot;">​</a></h2><p>編譯並執行 <code>build.zig</code> 中定義的 &quot;test&quot; 步驟。通常用於運行整個項目的測試。</p><h2 id="zig-init" tabindex="-1"><code>zig init</code> <a class="header-anchor" href="#zig-init" aria-label="Permalink to &quot;`zig init`&quot;">​</a></h2><p>初始化一個新的 Zig 項目。此命令會在當前目錄下創建 <code>build.zig</code>、<code>build.zig.zon</code> 和 <code>src</code> 目錄（包含 <code>main.zig</code> 和 <code>root.zig</code>）。</p><blockquote><p><strong>注意</strong>：在 Zig 0.12+ 版本中，原來的 <code>zig init-exe</code> 和 <code>zig init-lib</code> 命令已合併為統一的 <code>zig init</code> 命令。新的模板同時包含可執行文件和靜態庫的配置，用戶可以根據需要刪除不需要的部分。</p></blockquote><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                               # 項目根目錄</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">├──</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build.zig</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                   # Zig 構建腳本：定義如何編譯、測試和打包項目</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">├──</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build.zig.zon</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # 項目清單文件 (zon 是 Zig Object Notation)：聲明項目元數據和依賴項</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">└──</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                         # 源代碼目錄</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    ├──</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.zig</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # 程序主入口文件（可執行文件）</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    └──</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root.zig</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # 庫的根文件（靜態庫）</span></span></code></pre></div><h2 id="zig-ast-check" tabindex="-1"><code>zig ast-check</code> <a class="header-anchor" href="#zig-ast-check" aria-label="Permalink to &quot;`zig ast-check`&quot;">​</a></h2><p>對指定的源文件或從標準輸入讀取的代碼進行 AST (抽象語法樹) 級別的語法檢查。</p><h2 id="zig-fmt" tabindex="-1"><code>zig fmt</code> <a class="header-anchor" href="#zig-fmt" aria-label="Permalink to &quot;`zig fmt`&quot;">​</a></h2><p>格式化 Zig 源代碼文件。支持指定文件路徑，也支持從標準輸入（<code>stdin</code>）讀取內容。</p><h2 id="zig-test" tabindex="-1"><code>zig test</code> <a class="header-anchor" href="#zig-test" aria-label="Permalink to &quot;`zig test`&quot;">​</a></h2><p>編譯並運行指定源文件中的測試用例。非常適用於單元測試。</p><h2 id="zig-run" tabindex="-1"><code>zig run</code> <a class="header-anchor" href="#zig-run" aria-label="Permalink to &quot;`zig run`&quot;">​</a></h2><p>編譯並立即運行一個 Zig 程序。該命令對於快速測試代碼片段非常有用。</p><h2 id="zig-cc" tabindex="-1"><code>zig cc</code> <a class="header-anchor" href="#zig-cc" aria-label="Permalink to &quot;`zig cc`&quot;">​</a></h2><p>使用 Zig 的內置 C 編譯器來編譯 C 代碼。可以看作是 <code>gcc</code> 或 <code>clang</code> 的直接替代品。</p><h2 id="zig-c" tabindex="-1"><code>zig c++</code> <a class="header-anchor" href="#zig-c" aria-label="Permalink to &quot;`zig c++`&quot;">​</a></h2><p>使用 Zig 的內置 C++ 編譯器來編譯 C++ 代碼。可以看作是 <code>g++</code> 或 <code>clang++</code> 的直接替代品。</p><h2 id="zig-translate-c" tabindex="-1"><code>zig translate-c</code> <a class="header-anchor" href="#zig-translate-c" aria-label="Permalink to &quot;`zig translate-c`&quot;">​</a></h2><p>將 C 代碼自動轉換為 Zig 代碼。這是一個強大的功能，可以極大地幫助開發者將現有的 C 代碼庫遷移到 Zig。</p><h2 id="zig-targets" tabindex="-1"><code>zig targets</code> <a class="header-anchor" href="#zig-targets" aria-label="Permalink to &quot;`zig targets`&quot;">​</a></h2><p>列出 Zig 編譯器支持的所有目標架構、操作系統和 ABI (應用程序二進制接口)。</p><h2 id="zig-version" tabindex="-1"><code>zig version</code> <a class="header-anchor" href="#zig-version" aria-label="Permalink to &quot;`zig version`&quot;">​</a></h2><p>顯示當前安裝的 Zig 編譯器版本。</p><h2 id="zig-zen" tabindex="-1"><code>zig zen</code> <a class="header-anchor" href="#zig-zen" aria-label="Permalink to &quot;`zig zen`&quot;">​</a></h2><p>輸出 Zig 的設計哲學。</p><h2 id="zig-fetch" tabindex="-1"><code>zig fetch</code> <a class="header-anchor" href="#zig-fetch" aria-label="Permalink to &quot;`zig fetch`&quot;">​</a></h2><p>此命令用於獲取包的哈希值，或直接將包添加為項目的依賴項並記錄在 <code>build.zig.zon</code> 文件中。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 僅獲取包的哈希值</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/webui-dev/zig-webui/archive/main.tar.gz</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">12202809180bab2c7ae3382781b2fc65395e74b49d99ff2595f3fea9f7cf66cfa963</span></span></code></pre></div><p>如果你希望將包直接添加為依賴項，可以附加 <code>--save</code> 參數：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 獲取哈希值，並將其作為依賴項保存到 build.zig.zon</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --save</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/webui-dev/zig-webui/archive/main.tar.gz</span></span></code></pre></div><p>當包在其 <code>build.zig.zon</code> 中定義了 <code>name</code> 字段時，<code>zig fetch</code> 會自動使用該名稱。你也可以使用 <code>--save=&lt;custom-name&gt;</code> 來指定一個自定義的依賴名稱，例如 <code>--save=webuizig</code>。</p><p>除了以上介紹的命令，<code>zig</code> 還提供了許多其他命令和選項。隨著 Zig 語言的不斷發展，新的功能和命令也會持續加入，建議您定期查閱 <a href="https://ziglang.org/documentation/master/" target="_blank" rel="noreferrer">Zig 官方文檔</a> 以獲取最新信息。</p>',41)]))}const k=a(n,[["render",o]]);export{p as __pageData,k as default};
